-- 03_features.sql: one row of features per readout, all splits -> readout_features.
-- GENERATED by src/make_features_sql.py -- edit that script, not this file.
--
-- No look-ahead: every window is PARTITION BY split, vehicle_id ORDER BY time_step and
-- reaches only backwards (lag, or ROWS BETWEEN 4 PRECEDING AND CURRENT ROW). There is
-- no FOLLOWING, lead() or whole-partition aggregate, so a feature at readout t uses only
-- readouts at or before t. tests/test_no_lookahead.py proves this by truncation.
--
-- 'Last 5 readouts' = the current readout and the 4 before it. Vehicles with fewer than
-- 5 readouts so far use what exists; readouts_so_far tells the model how much history
-- there was. Features at a vehicle's first readout that need a previous one are NULL.
-- Counters and histograms are cumulative (they decrease in < 0.5% of consecutive
-- readouts; kept as is), so changes and rates carry the recent signal.
-- Only reads table `readouts`.

CREATE OR REPLACE TABLE readout_features AS
WITH base AS (
    -- Per readout: counter levels and three linear histogram aggregates
    -- (total count, bin-index-weighted sum, count in the top 2 bins). Missing bins count as 0.
    SELECT
        split,
        vehicle_id,
        time_step,
        "171_0" AS c171,
        "666_0" AS c666,
        "427_0" AS c427,
        "837_0" AS c837,
        "309_0" AS c309,
        "835_0" AS c835,
