        (1 * coalesce("167_1", 0) + 2 * coalesce("167_2", 0) + 3 * coalesce("167_3", 0) + 4 * coalesce("167_4", 0) + 5 * coalesce("167_5", 0) + 6 * coalesce("167_6", 0) + 7 * coalesce("167_7", 0) + 8 * coalesce("167_8", 0) + 9 * coalesce("167_9", 0)) AS h167_wsum,
        (coalesce("167_8", 0) + coalesce("167_9", 0)) AS h167_top2,
        (coalesce("272_0", 0) + coalesce("272_1", 0) + coalesce("272_2", 0) + coalesce("272_3", 0) + coalesce("272_4", 0) + coalesce("272_5", 0) + coalesce("272_6", 0) + coalesce("272_7", 0) + coalesce("272_8", 0) + coalesce("272_9", 0)) AS h272_total,
        (1 * coalesce("272_1", 0) + 2 * coalesce("272_2", 0) + 3 * coalesce("272_3", 0) + 4 * coalesce("272_4", 0) + 5 * coalesce("272_5", 0) + 6 * coalesce("272_6", 0) + 7 * coalesce("272_7", 0) + 8 * coalesce("272_8", 0) + 9 * coalesce("272_9", 0)) AS h272_wsum,
        (coalesce("272_8", 0) + coalesce("272_9", 0)) AS h272_top2,
        (coalesce("291_0", 0) + coalesce("291_1", 0) + coalesce("291_2", 0) + coalesce("291_3", 0) + coalesce("291_4", 0) + coalesce("291_5", 0) + coalesce("291_6", 0) + coalesce("291_7", 0) + coalesce("291_8", 0) + coalesce("291_9", 0) + coalesce("291_10", 0)) AS h291_total,
        (1 * coalesce("291_1", 0) + 2 * coalesce("291_2", 0) + 3 * coalesce("291_3", 0) + 4 * coalesce("291_4", 0) + 5 * coalesce("291_5", 0) + 6 * coalesce("291_6", 0) + 7 * coalesce("291_7", 0) + 8 * coalesce("291_8", 0) + 9 * coalesce("291_9", 0) + 10 * coalesce("291_10", 0)) AS h291_wsum,
        (coalesce("291_9", 0) + coalesce("291_10", 0)) AS h291_top2,
        (coalesce("158_0", 0) + coalesce("158_1", 0) + coalesce("158_2", 0) + coalesce("158_3", 0) + coalesce("158_4", 0) + coalesce("158_5", 0) + coalesce("158_6", 0) + coalesce("158_7", 0) + coalesce("158_8", 0) + coalesce("158_9", 0)) AS h158_total,
        (1 * coalesce("158_1", 0) + 2 * coalesce("158_2", 0) + 3 * coalesce("158_3", 0) + 4 * coalesce("158_4", 0) + 5 * coalesce("158_5", 0) + 6 * coalesce("158_6", 0) + 7 * coalesce("158_7", 0) + 8 * coalesce("158_8", 0) + 9 * coalesce("158_9", 0)) AS h158_wsum,
        (coalesce("158_8", 0) + coalesce("158_9", 0)) AS h158_top2,
        (coalesce("459_0", 0) + coalesce("459_1", 0) + coalesce("459_2", 0) + coalesce("459_3", 0) + coalesce("459_4", 0) + coalesce("459_5", 0) + coalesce("459_6", 0) + coalesce("459_7", 0) + coalesce("459_8", 0) + coalesce("459_9", 0) + coalesce("459_10", 0) + coalesce("459_11", 0) + coalesce("459_12", 0) + coalesce("459_13", 0) + coalesce("459_14", 0) + coalesce("459_15", 0) + coalesce("459_16", 0) + coalesce("459_17", 0) + coalesce("459_18", 0) + coalesce("459_19", 0)) AS h459_total,
        (1 * coalesce("459_1", 0) + 2 * coalesce("459_2", 0) + 3 * coalesce("459_3", 0) + 4 * coalesce("459_4", 0) + 5 * coalesce("459_5", 0) + 6 * coalesce("459_6", 0) + 7 * coalesce("459_7", 0) + 8 * coalesce("459_8", 0) + 9 * coalesce("459_9", 0) + 10 * coalesce("459_10", 0) + 11 * coalesce("459_11", 0) + 12 * coalesce("459_12", 0) + 13 * coalesce("459_13", 0) + 14 * coalesce("459_14", 0) + 15 * coalesce("459_15", 0) + 16 * coalesce("459_16", 0) + 17 * coalesce("459_17", 0) + 18 * coalesce("459_18", 0) + 19 * coalesce("459_19", 0)) AS h459_wsum,
        (coalesce("459_18", 0) + coalesce("459_19", 0)) AS h459_top2,
        (coalesce("397_0", 0) + coalesce("397_1", 0) + coalesce("397_2", 0) + coalesce("397_3", 0) + coalesce("397_4", 0) + coalesce("397_5", 0) + coalesce("397_6", 0) + coalesce("397_7", 0) + coalesce("397_8", 0) + coalesce("397_9", 0) + coalesce("397_10", 0) + coalesce("397_11", 0) + coalesce("397_12", 0) + coalesce("397_13", 0) + coalesce("397_14", 0) + coalesce("397_15", 0) + coalesce("397_16", 0) + coalesce("397_17", 0) + coalesce("397_18", 0) + coalesce("397_19", 0) + coalesce("397_20", 0) + coalesce("397_21", 0) + coalesce("397_22", 0) + coalesce("397_23", 0) + coalesce("397_24", 0) + coalesce("397_25", 0) + coalesce("397_26", 0) + coalesce("397_27", 0) + coalesce("397_28", 0) + coalesce("397_29", 0) + coalesce("397_30", 0) + coalesce("397_31", 0) + coalesce("397_32", 0) + coalesce("397_33", 0) + coalesce("397_34", 0) + coalesce("397_35", 0)) AS h397_total,
        (1 * coalesce("397_1", 0) + 2 * coalesce("397_2", 0) + 3 * coalesce("397_3", 0) + 4 * coalesce("397_4", 0) + 5 * coalesce("397_5", 0) + 6 * coalesce("397_6", 0) + 7 * coalesce("397_7", 0) + 8 * coalesce("397_8", 0) + 9 * coalesce("397_9", 0) + 10 * coalesce("397_10", 0) + 11 * coalesce("397_11", 0) + 12 * coalesce("397_12", 0) + 13 * coalesce("397_13", 0) + 14 * coalesce("397_14", 0) + 15 * coalesce("397_15", 0) + 16 * coalesce("397_16", 0) + 17 * coalesce("397_17", 0) + 18 * coalesce("397_18", 0) + 19 * coalesce("397_19", 0) + 20 * coalesce("397_20", 0) + 21 * coalesce("397_21", 0) + 22 * coalesce("397_22", 0) + 23 * coalesce("397_23", 0) + 24 * coalesce("397_24", 0) + 25 * coalesce("397_25", 0) + 26 * coalesce("397_26", 0) + 27 * coalesce("397_27", 0) + 28 * coalesce("397_28", 0) + 29 * coalesce("397_29", 0) + 30 * coalesce("397_30", 0) + 31 * coalesce("397_31", 0) + 32 * coalesce("397_32", 0) + 33 * coalesce("397_33", 0) + 34 * coalesce("397_34", 0) + 35 * coalesce("397_35", 0)) AS h397_wsum,
        (coalesce("397_34", 0) + coalesce("397_35", 0)) AS h397_top2
    FROM readouts
),
win AS (
    -- Backward-looking window values: previous readout (lag) and the oldest readout in
    -- the 5-readout window (first_value over w5).
    SELECT
        *,
        row_number() OVER w AS readouts_so_far,
        lag(time_step) OVER w AS ts_prev,
        first_value(time_step) OVER w5 AS ts_5,
        lag(c171) OVER w AS c171_prev,
        first_value(c171) OVER w5 AS c171_5,
        lag(c666) OVER w AS c666_prev,
        first_value(c666) OVER w5 AS c666_5,
        lag(c427) OVER w AS c427_prev,
        first_value(c427) OVER w5 AS c427_5,
        lag(c837) OVER w AS c837_prev,
        first_value(c837) OVER w5 AS c837_5,
        lag(c309) OVER w AS c309_prev,
        first_value(c309) OVER w5 AS c309_5,
        lag(c835) OVER w AS c835_prev,
        first_value(c835) OVER w5 AS c835_5,
        lag(c370) OVER w AS c370_prev,
        first_value(c370) OVER w5 AS c370_5,
        lag(c100) OVER w AS c100_prev,
        first_value(c100) OVER w5 AS c100_5,
        first_value(h167_total) OVER w5 AS h167_total_5,
        first_value(h167_wsum) OVER w5 AS h167_wsum_5,
        first_value(h167_top2) OVER w5 AS h167_top2_5,
        first_value(h272_total) OVER w5 AS h272_total_5,
        first_value(h272_wsum) OVER w5 AS h272_wsum_5,
        first_value(h272_top2) OVER w5 AS h272_top2_5,
        first_value(h291_total) OVER w5 AS h291_total_5,
        first_value(h291_wsum) OVER w5 AS h291_wsum_5,
        first_value(h291_top2) OVER w5 AS h291_top2_5,
        first_value(h158_total) OVER w5 AS h158_total_5,
        first_value(h158_wsum) OVER w5 AS h158_wsum_5,
        first_value(h158_top2) OVER w5 AS h158_top2_5,
        first_value(h459_total) OVER w5 AS h459_total_5,
        first_value(h459_wsum) OVER w5 AS h459_wsum_5,
        first_value(h459_top2) OVER w5 AS h459_top2_5,
        first_value(h397_total) OVER w5 AS h397_total_5,
        first_value(h397_wsum) OVER w5 AS h397_wsum_5,
        first_value(h397_top2) OVER w5 AS h397_top2_5
    FROM base
    WINDOW w  AS (PARTITION BY split, vehicle_id ORDER BY time_step),
           w5 AS (PARTITION BY split, vehicle_id ORDER BY time_step ROWS BETWEEN 4 PRECEDING AND CURRENT ROW)
)
SELECT
    split,
    vehicle_id,

    -- Timing: operating time, history length, gap since the previous readout and
    -- span of the last 5 readouts (readouts are irregular, so rates divide by these).
    time_step,
    readouts_so_far,
    time_step - ts_prev AS dt_prev,
    nullif(time_step - ts_5, 0) AS dt_last5,

    -- Counter levels: raw cumulative values (lifetime usage).
    c171 AS c171_level,
    c666 AS c666_level,
    c427 AS c427_level,
    c837 AS c837_level,
    c309 AS c309_level,
    c835 AS c835_level,
    c370 AS c370_level,
    c100 AS c100_level,

    -- Counter change since the previous readout, and per time step.
    c171 - c171_prev AS c171_delta_prev,
    (c171 - c171_prev) / nullif(time_step - ts_prev, 0) AS c171_rate_prev,
    c666 - c666_prev AS c666_delta_prev,
    (c666 - c666_prev) / nullif(time_step - ts_prev, 0) AS c666_rate_prev,
    c427 - c427_prev AS c427_delta_prev,
    (c427 - c427_prev) / nullif(time_step - ts_prev, 0) AS c427_rate_prev,
    c837 - c837_prev AS c837_delta_prev,
    (c837 - c837_prev) / nullif(time_step - ts_prev, 0) AS c837_rate_prev,
    c309 - c309_prev AS c309_delta_prev,
    (c309 - c309_prev) / nullif(time_step - ts_prev, 0) AS c309_rate_prev,
    c835 - c835_prev AS c835_delta_prev,
    (c835 - c835_prev) / nullif(time_step - ts_prev, 0) AS c835_rate_prev,
    c370 - c370_prev AS c370_delta_prev,
    (c370 - c370_prev) / nullif(time_step - ts_prev, 0) AS c370_rate_prev,
    c100 - c100_prev AS c100_delta_prev,
    (c100 - c100_prev) / nullif(time_step - ts_prev, 0) AS c100_rate_prev,

    -- Counter change over the last 5 readouts, and per time step (recent usage intensity).
    CASE WHEN readouts_so_far > 1 THEN c171 - c171_5 END AS c171_delta_5,
    (c171 - c171_5) / nullif(time_step - ts_5, 0) AS c171_rate_5,
    CASE WHEN readouts_so_far > 1 THEN c666 - c666_5 END AS c666_delta_5,
    (c666 - c666_5) / nullif(time_step - ts_5, 0) AS c666_rate_5,
    CASE WHEN readouts_so_far > 1 THEN c427 - c427_5 END AS c427_delta_5,
    (c427 - c427_5) / nullif(time_step - ts_5, 0) AS c427_rate_5,
    CASE WHEN readouts_so_far > 1 THEN c837 - c837_5 END AS c837_delta_5,
    (c837 - c837_5) / nullif(time_step - ts_5, 0) AS c837_rate_5,
    CASE WHEN readouts_so_far > 1 THEN c309 - c309_5 END AS c309_delta_5,
    (c309 - c309_5) / nullif(time_step - ts_5, 0) AS c309_rate_5,
    CASE WHEN readouts_so_far > 1 THEN c835 - c835_5 END AS c835_delta_5,
    (c835 - c835_5) / nullif(time_step - ts_5, 0) AS c835_rate_5,
    CASE WHEN readouts_so_far > 1 THEN c370 - c370_5 END AS c370_delta_5,
    (c370 - c370_5) / nullif(time_step - ts_5, 0) AS c370_rate_5,
    CASE WHEN readouts_so_far > 1 THEN c100 - c100_5 END AS c100_delta_5,
    (c100 - c100_5) / nullif(time_step - ts_5, 0) AS c100_rate_5,

    -- Histogram lifetime summaries (cumulative histogram): total count, weighted mean
    -- bin index (0 = lowest bin), share in the top 2 bins, and change in mean bin over
    -- the last 5 readouts. These move slowly because the histogram is cumulative.
    h167_total,
    h167_wsum / nullif(h167_total, 0) AS h167_mean_bin,
    h167_top2 / nullif(h167_total, 0) AS h167_top2_share,
    CASE WHEN readouts_so_far > 1 THEN h167_wsum / nullif(h167_total, 0) - h167_wsum_5 / nullif(h167_total_5, 0) END AS h167_mean_bin_change_5,
    h272_total,
    h272_wsum / nullif(h272_total, 0) AS h272_mean_bin,
    h272_top2 / nullif(h272_total, 0) AS h272_top2_share,
    CASE WHEN readouts_so_far > 1 THEN h272_wsum / nullif(h272_total, 0) - h272_wsum_5 / nullif(h272_total_5, 0) END AS h272_mean_bin_change_5,
    h291_total,
    h291_wsum / nullif(h291_total, 0) AS h291_mean_bin,
    h291_top2 / nullif(h291_total, 0) AS h291_top2_share,
    CASE WHEN readouts_so_far > 1 THEN h291_wsum / nullif(h291_total, 0) - h291_wsum_5 / nullif(h291_total_5, 0) END AS h291_mean_bin_change_5,
    h158_total,
    h158_wsum / nullif(h158_total, 0) AS h158_mean_bin,
    h158_top2 / nullif(h158_total, 0) AS h158_top2_share,
    CASE WHEN readouts_so_far > 1 THEN h158_wsum / nullif(h158_total, 0) - h158_wsum_5 / nullif(h158_total_5, 0) END AS h158_mean_bin_change_5,
    h459_total,
    h459_wsum / nullif(h459_total, 0) AS h459_mean_bin,
    h459_top2 / nullif(h459_total, 0) AS h459_top2_share,
    CASE WHEN readouts_so_far > 1 THEN h459_wsum / nullif(h459_total, 0) - h459_wsum_5 / nullif(h459_total_5, 0) END AS h459_mean_bin_change_5,
    h397_total,
    h397_wsum / nullif(h397_total, 0) AS h397_mean_bin,
    h397_top2 / nullif(h397_total, 0) AS h397_top2_share,
    CASE WHEN readouts_so_far > 1 THEN h397_wsum / nullif(h397_total, 0) - h397_wsum_5 / nullif(h397_total_5, 0) END AS h397_mean_bin_change_5,

    -- Histogram recent-window summaries: the same summaries on the histogram INCREMENT
    -- over the last 5 readouts (now minus 4 readouts back), i.e. how the vehicle was used
    -- recently rather than over its whole life. NULL when the increment total is <= 0
    -- (first readout, or a rare decrease in the cumulative counts).
    (h167_wsum - h167_wsum_5) / CASE WHEN (h167_total - h167_total_5) > 0 THEN (h167_total - h167_total_5) END AS h167_recent5_mean_bin,
    (h167_top2 - h167_top2_5) / CASE WHEN (h167_total - h167_total_5) > 0 THEN (h167_total - h167_total_5) END AS h167_recent5_top2_share,
    (h272_wsum - h272_wsum_5) / CASE WHEN (h272_total - h272_total_5) > 0 THEN (h272_total - h272_total_5) END AS h272_recent5_mean_bin,
    (h272_top2 - h272_top2_5) / CASE WHEN (h272_total - h272_total_5) > 0 THEN (h272_total - h272_total_5) END AS h272_recent5_top2_share,
    (h291_wsum - h291_wsum_5) / CASE WHEN (h291_total - h291_total_5) > 0 THEN (h291_total - h291_total_5) END AS h291_recent5_mean_bin,
    (h291_top2 - h291_top2_5) / CASE WHEN (h291_total - h291_total_5) > 0 THEN (h291_total - h291_total_5) END AS h291_recent5_top2_share,
    (h158_wsum - h158_wsum_5) / CASE WHEN (h158_total - h158_total_5) > 0 THEN (h158_total - h158_total_5) END AS h158_recent5_mean_bin,
    (h158_top2 - h158_top2_5) / CASE WHEN (h158_total - h158_total_5) > 0 THEN (h158_total - h158_total_5) END AS h158_recent5_top2_share,
    (h459_wsum - h459_wsum_5) / CASE WHEN (h459_total - h459_total_5) > 0 THEN (h459_total - h459_total_5) END AS h459_recent5_mean_bin,
    (h459_top2 - h459_top2_5) / CASE WHEN (h459_total - h459_total_5) > 0 THEN (h459_total - h459_total_5) END AS h459_recent5_top2_share,
    (h397_wsum - h397_wsum_5) / CASE WHEN (h397_total - h397_total_5) > 0 THEN (h397_total - h397_total_5) END AS h397_recent5_mean_bin,
    (h397_top2 - h397_top2_5) / CASE WHEN (h397_total - h397_total_5) > 0 THEN (h397_total - h397_total_5) END AS h397_recent5_top2_share
FROM win
ORDER BY split, vehicle_id, time_step;
